"""Idempotent editorial corrections; run after author-dutch-practice.py.

Keep recordings and main sentences stable. Correct over-absolute claims and
contrast examples that are actually possible Dutch in a different context.
"""
import json,re,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
def read(n):return json.loads((root/'data'/n).read_text())
b=read('grammar-breakdowns.json');notes=read('grammar-notes.json')
# Teaching the verb bracket is more accurate than saying every verb is the last word.
for key,x in b.items():
 # Subject je/jij must FOLLOW the finite verb for the ordinary added -t to disappear.
 # A stem-final t is retained: laten -> laat je, not la je.
 for field in ['order','forms','compare']:
  x[field]=x[field].replace('drops after je','drops when subject je/jij follows the finite verb')
 x['mistake']['why']=x['mistake']['why'].replace('drops after je','drops when subject je/jij follows the finite verb')
 for field in ['order','compare']:
  x[field]=x[field].replace('goes to the very end','usually closes the verb bracket').replace('moves to the very end','comes toward the end of its subordinate clause').replace('at the very end','in the final verb bracket').replace('goes to the end','normally occurs toward the end').replace('the verb is always second','the finite verb is second in this main clause')
  if 'imperative' in x['parts'][0]['label']:
   x[field]=x[field].replace('while the verb itself stays second','while the imperative verb comes first')
 for field in ['rule']:
  notes[key][field]=notes[key][field].replace('the verb is always second','the finite verb is second in an ordinary main clause').replace('always goes to the end','usually closes the verb bracket')
 # A statement-order echo question is possible. Do not cross it out as ungrammatical.
 wrong=x['mistake']['wrong'];parts=x['parts']
 subj=next((p['text'] for p in parts if p['label']=='subject'),None)
 finite=next((p['text'] for p in parts if 'finite verb' in p['label']),None)
 if wrong.endswith('?') and subj and finite and wrong.lower().startswith((subj+' '+finite+' ').lower()):
  x['mistake']['alternative']=True
  x['mistake']['why']='This statement order can be used as an echo or confirmation question, with questioning intonation. For an ordinary neutral yes/no question, put the finite verb before the subject, as in the model.'
for x in b.values():
 if 'niet een' in x['mistake']['wrong'].lower():
  x['mistake']['alternative']=True
  x['mistake']['why']='Niet een can express contrast or emphasis. To simply negate an indefinite noun phrase in this intended meaning, the ordinary form is geen. The model practises that unmarked negative form.'
# These are grammatical contrasts, not a general ban on an alternative word order/meaning.
contrasts={
 'work-15':'A prepositional phrase such as over het project may also follow gesproken. Both orders are possible. This card practises the common verb-bracket order, with the topic before the participle.',
 'conversation-59':'A full prepositional phrase can follow the infinitive. Both orders are possible; the model practises the phrase before geloven.',
 'conversation-78':'Both orders occur. In the model, waarom represents an omitted embedded reason question after weten. Ik wil waarom weten can stress the reason word itself. Practise the taught sentence without treating every other order as wrong.',
 'conversation-18':'Both hebben and zijn occur with vergeten, with differences in meaning and regional preference. Zijn is especially common for no longer remembering something; hebben is common for failing to do something. Do not treat heb ... vergeten as automatically ungrammatical.',
 'school-21':'Vergeten can use hebben or zijn depending on meaning and usage. The model uses zijn for no longer remembering the answer; the hebben version is not automatically an error.',
 'leisure-14':'Putting niet before de wedstrijd can create contrast: not the match, but something else. After the object it normally negates losing that match as a whole. The position depends on what you negate.',
 'weather-14':'De herfst komt is possible Dutch. Eraan adds the sense that autumn is approaching; it is not required in every sentence with komen.',
 'food-14':'Graag is commonly early in the middle of the clause, but it is not required to follow the finite verb immediately in every context.',
 'conversation-46':'Zij komen aan means they are arriving. Zij komen eraan means they are on their way/approaching. Both are grammatical, but the intended situation differs.',
 'home-08':'Er is melk in de koelkast is grammatical. Staat can describe a container standing in the fridge. Dutch often chooses a position verb, but is is not forbidden.',
 'school-07':'Mijn pen is op tafel is grammatical. Ligt more precisely describes a pen lying on the table. A position verb is useful, not compulsory.',
 'transport-01':'The model keeps van welk spoor together. Stranding van can occur in informal speech, but this card teaches the neutral complete fronted prepositional phrase.',
 'work-10':'Hieraan normally precedes samenwerken in this compact model. Learn this preferred model order rather than assuming all adverbs must always occur in a single fixed position.',
 'administration-02':'A full destination phrase may follow an infinitive. The model places naar me before opsturen; the other order is possible.',
 'conversation-33':'Hartelijk dank is the conventional standalone formula. With a possessive, the adjective is inflected: mijn hartelijke dank. Learn the fixed expression rather than generalising that hartelijk never takes -e.',
 'home-11':'Op zoek zijn naar is an idiom meaning be looking for. Dutch also has the ordinary verb zoeken: Ze zochten een flat. The issue in the first phrase is using a bare infinitive after waren.',
 'work-27':'Beginnen can take a direct object (een gesprek beginnen). Beginnen met explicitly introduces the activity begun here; met is not obligatory with every use of beginnen.',
 'work-64':'The model makes the beneficiary explicit with voor ons. Bare indirect objects are possible with some verbs and contexts; they are not a universal substitute for every voor-phrase.'
}
for key,why in contrasts.items():b[key]['mistake'].update(alternative=True,why=why)
# Specific forms, natural equivalents and the questions David asked while studying.
fixes={
 'transport-01':{'forms':'Vertrekken is irregular: ik vertrek, hij vertrekt; past vertrok/vertrokken; perfect is vertrokken. Welk modifies singular het spoor; welke modifies a singular de-word or a plural.'},
 'conversation-21':{'forms':'Het eens zijn met means agree with. Met becomes mee in a pronominal adverb: daar + mee = daarmee. Ik ben het daarmee eens means I agree with that.'},
 'home-15':{'forms':'Uitdoen: ik doe ... uit, ik deed ... uit, ik heb uitgedaan. In the participle, ge goes between the separable prefix uit and the stem: uit + ge + daan.'},
 'work-16':{'forms':'Afronden: we ronden ... af; we hebben afgerond. The participle contains ge between the separable prefix af and rond: af + ge + rond. Hadden afgerond is past perfect.'},
 'transport-23':{'forms':'Both vrijdag and op vrijdag are possible time expressions. Op vakantie means on holiday. Keep the holiday phrase separate from the day: Ze vertrekken vrijdag op vakantie, or Ze vertrekken op vrijdag op vakantie.'},
 'school-21':{'forms':'Weten: ik weet; simple past wist/wisten. Vergeten has participle vergeten and can use hebben or zijn. Here ben ... vergeten describes no longer remembering the answer.'},
 'conversation-18':{'forms':'Ik ben vergeten is a perfect with zijn. Vergeten can also use hebben in appropriate contexts. Je before naam is possessive your, not the subject pronoun you.'},
 'conversation-33':{'order':'Hartelijk dank is a conventional thank-you formula, without a finite verb or a subject. It is not a sentence requiring V2 order.','forms':'The standalone expression uses hartelijk dank. After a possessive, use the inflected adjective: mijn hartelijke dank. This formula is exceptional; it does not establish a general rule for all de-word adjectives.'},
 'conversation-78':{'order':'Ik is the subject and wil the finite modal. Weten is an infinitive after wil. Waarom stands for the reason you want to know; this omitted embedded question can follow weten. The last word is therefore not always the action verb.'},
 'food-07':{'forms':'Proberen: ik probeer (present), ik probeerde / wij probeerden (simple past), ik heb geprobeerd (perfect). The regular participle is ge + probeer + d. Het gerecht means the dish; het-word + indefinite een gives een nieuw gerecht. Compare de soep → een nieuwe soep, and het definite noun phrase het nieuwe gerecht.'},
 'leisure-10':{'forms':'Dansen: ik dans; past ik danste / wij dansten; perfect ik heb gedanst. The stem ends in s, so the regular past uses -te and participle -t. Met mijn vrouw means with my wife. Op de receptie names the reception event; aan de receptie commonly means at the reception desk. In describes a physical room or space.'},
 'home-09':{'forms':'Opruimen means tidy up or put things away: ik ruim ... op; perfect ik heb opgeruimd. Schoonmaken means clean dirt away: ik maak ... schoon; perfect ik heb schoongemaakt. You can tidy a room without cleaning it, or clean its floor after putting things away.'},
 'home-23':{'forms':'Bezig met can introduce a noun (de was = laundry) or an infinitive naming an activity (het wassen = washing). Het schoonmaken van de ramen is a noun-like cleaning phrase. Compare Hij is de ramen aan het schoonmaken, the verbal progressive. De koken is incorrect: a nominalised infinitive takes het.'},
 'work-150':{'forms':'Verkopen is inseparable: verkoop, verkocht, heeft verkocht. Verkoop is the imperative stem. Je in Verkoop je auto means your; Verkoop je de auto? instead has subject je and asks are you selling? Aan introduces the buyer; te introduces an infinitive, not a buyer. Naar also occurs in non-movement expressions such as luisteren naar, so it is not simply a movement-only word.'},
 'work-80':{'forms':'The first je is the subject, so question-form hebt becomes heb: Heb je ...? The second je is possessive your before taak. Afmaken: maak ... af; perfect afgemaakt. For object it, use Heb je het al afgemaakt? Unstressed het normally comes early in the middle of the clause, before al and the participle.'},
 'work-145':{'forms':'Ons and onze both mean our. Budget is singular and takes het, so use ons budget. Use onze before a singular de-word (onze auto) and every plural (onze budgetten). The number of owners does not decide the ending. We plannen is the plural present of plannen; Ik plande is simple past and We hebben gepland is perfect.'}
}
fixes.update({
 'school-04':{'meaning':'Politely asking for a brief opportunity to ask a question.','forms':'Mag is the first-person singular of mogen. Iets means something and vragen is the infinitive. Even softens the request and suggests taking a moment; it does not demand that the question be spoken at high speed.','compare':'A natural English equivalent is May I ask a quick question? Dutch keeps vragen as an infinitive after mag and places even iets before it.'},
 'school-05':{'forms':'This perfect uses hebben: ik heb mijn huiswerk gemaakt. Heb is finite and gemaakt is the participle of maken. Al means already. Mijn is possessive my and stays the same before de- and het-words. The perfect does not always use hebben: some verbs and meanings use zijn, as in ik ben vertrokken.'},
 'school-08':{'compare':'English Tomorrow I am going keeps the subject before the verb. In Dutch, morgen is the first constituent, then finite ga comes before subject ik. The verb is second in the whole clause, not the first word.'},
 'transport-01':{'forms':'Vertrekken is irregular: ik vertrek, hij vertrekt; past vertrok/vertrokken; perfect is vertrokken. Welk modifies singular het spoor; welke modifies a singular de-word or a plural.','compare':'English allows From which platform does the train depart? and Which platform does the train depart from? The Dutch model keeps the complete phrase van welk spoor first, followed by finite vertrekt and subject de trein.'},
 'transport-02':{'forms':'Moeten: ik moet. Here moet is finite, so overstappen stays together as an infinitive. When overstappen itself is finite in a main clause, it splits: ik stap over. Perfect: ik ben overgestapt. Overstappen means transferring from one vehicle or connection to another, not necessarily only trains.'},
 'transport-08':{'compare':'English places buy before its object my ticket. Dutch puts the object mijn ticket before infinitive kopen, while finite kan follows waar and precedes subject ik.'},
 'home-03':{'forms':'This perfect uses hebben: heb je ... gedaan? Doen has participle gedaan. Compare statement je hebt and question heb je: subject je follows the auxiliary, so the ordinary added -t is omitted. De deur op slot doen means lock the door. Other perfects may use zijn, depending on verb and meaning.'},
 'home-06':{'forms':'Dit is a standalone demonstrative introducing an identification: dit is jouw kopje. It is not an adjective attached to kopje. Dutch can also say Dit is jouw tas even though tas is a de-word. Before a noun directly, use dit kopje but deze tas. Jouw/je means your; jou is the object form you.'},
 'home-08':{'forms':'Staan: singular er staat, plural er staan. Milk is understood through its container here, such as a standing carton or bottle. Compare Er staan twee pakken melk in de koelkast. Er is melk is also grammatical and simply states availability.'},
 'conversation-01':{'forms':'Spreken: ik spreek, jij/hij spreekt, wij spreken; simple past sprak/spraken; perfect heb/heeft gesproken. Een beetje means a little. The language name has no article in een beetje Nederlands spreken. An article is possible in other constructions, such as het Nederlands van vandaag (the Dutch of today).'},
 'conversation-04':{'forms':'Wonen: ik woon, jij woont, wij wonen; past woonde/woonden; perfect heb gewoond. With this city name use in Roeselare. Also in Gent and in België. This is not a claim that every geographical name always takes in.'},
 'transport-10':{'order':'Kunt is the finite modal and starts this polite yes/no question, followed by subject u. Mij is the person receiving help. Helpen stays an infinitive after kunt. The full prepositional phrase met mijn bagage naturally follows helpen here; closing the verb bracket does not mean being the last word of the sentence.','forms':'Kunnen: u kunt or u kan; both are standard. Mij means me, while mijn means my. Helpen met iets means help with something. Kunt u mij met mijn bagage helpen? is another natural order.'},
 'conversation-37':{'forms':'Terugbellen means call back. Here zal is finite and terugbellen stays together as an infinitive. When terugbellen itself is the finite verb in a main clause, it splits: hij belt terug. Perfect: hij heeft teruggebeld.'},
 'food-11':{'order':'Waar is the first question constituent, followed by finite is. The complete subject is de zak met eten: met eten describes what the bag contains, so it belongs inside the noun phrase.'},
 'conversation-56':{'order':'Wie is itself the subject in this question, meaning who. Is is the finite verb; daar says where and nu says when. There is no extra subject after is. Contrast Waar is de dokter?, where waar asks about place and de dokter is the subject.','forms':'The model uses singular is when asking who is there. Wie does not inherently mean exactly one person: plural agreement is possible in suitable contexts, as in Wie zijn dat? Learn the whole question rather than a rule that wie is always singular.'},
 'conversation-63':{'forms':'Laten zien means show: je laat het me zien, and Laat je het me zien? with question order. Laat is the stem of laten. Its t stays when subject je/jij follows: laat je, never la je. Only an added second-person -t is omitted in inversion; a stem-final t is retained. Zien remains an infinitive after finite laat.'},
 'health-07':{'order':'Ze is the shared subject of two coordinated actions: werd wakker and voelde zich veel beter. En joins them. The second action leaves out the repeated subject ze; voelde still agrees with that same woman. Werd and voelde are both finite past verbs, not an infinitive pair.'},
 'school-17':{'forms':'Leren: ik leer, ik leerde, ik heb geleerd. In iets nieuws, iets means something and nieuw is an adjective used with the ending -s. This is something new; the separate noun het nieuws means the news. The -s here is not a plural ending. Compare iets leuks (something nice), niets nieuws (nothing new), and een nieuw boek (a new book, without that -s).'},
 'food-15':{'forms':'Zitten te wachten describes waiting while seated. In the perfect, zitten appears as a replacement infinitive before wachten: ze heeft zitten wachten, not ze heeft gezeten wachten. Heeft is finite; zitten and wachten are infinitives. Een uur gives the duration. The literal seated posture is part of this situation, although posture verbs can also emphasise an ongoing activity.'},
 'work-09':{'order':'Ze is the subject, meaning she in this situation; is is the finite form of zijn. Druk bezig describes being occupied. Met introduces the noun-like activity het schrijven van een e-mail.','forms':'An infinitive used as an activity noun takes het: het schrijven, not de schrijven. Van een e-mail names what is being written. Compare the verbal progressive Ze is druk een e-mail aan het schrijven: aan het takes the infinitive schrijven, with een e-mail as its object.'}
})
fixes.update({
 'conversation-11':{'forms':'Zich zorgen maken over means worry about. Match the reflexive to the person worrying: ik maak me, jij maakt je, hij maakt zich, wij maken ons. Here hij is worried about losing his own keys. Het verliezen names an activity as a noun; van zijn sleutels says what he might lose. Zijn means his before sleutels, not the verb be.'},
 'work-03':{'forms':'Eindigen has stem eindig. Singular simple past adds -de: de vergadering eindigde. Plural adds -den: de vergaderingen eindigden. These are forms of this verb, not a rule that every singular past ends in -de; other regular verbs use -te, and irregular verbs have their own forms.'},
 'conversation-14':{'forms':'This perfect uses hebben: we hebben urenlang gepraat. Hebben is finite and agrees with plural we; gepraat is the participle of praten. The perfect can use zijn with other verbs/meanings, such as we zijn vertrokken. Compare simple past we praatten, with double t, and present we praten. Urenlang means for hours.'},
 'conversation-16':{'forms':'Zul je and zal je are both standard future questions. Compare je zult with zul je, where subject je follows the finite verb and the added -t is omitted. Hulp nodig hebben means need help: hebben remains an infinitive after zul/zal, with hulp nodig between the finite verb and infinitive.'},
 'work-05':{'practiceGuide':'Klaar met means finished with; bezig met means busy with. Both can introduce a noun-like activity: het lezen van het rapport. Compare Hij is klaar met lezen (finished reading) and Hij is bezig met lezen (still occupied with reading). The related examples practise naming activities and this contrast; being busy does not mean being finished.'}
})
fixes.update({
 'conversation-18':{'compare':'English uses have in I have forgotten your name. Dutch commonly uses zijn here: ik ben je naam vergeten. Ben is a perfect auxiliary in this sentence, not a passive meaning that someone has forgotten the speaker.'},
 'home-12':{'forms':'Blijven: ik blijf, ik bleef, ik ben gebleven. Liever is the comparative of graag and expresses a preference. Ik blijf liever thuis means I would rather stay home; liever does not itself mark a past or conditional tense. In this model it follows finite blijf, but adverb position depends on the rest of the clause.'},
 'conversation-19':{'forms':'Klinken: het klinkt; simple past het klonk, plural klonken; perfect het heeft geklonken. Enigszins means somewhat and is fairly formal. Vreemd describes how it sounded: it is a predicate adjective after linking klonk and has no attributive -e. Compare a noun phrase with an adjective: een vreemd geluid, het vreemde geluid.'},
 'conversation-21':{'compare':'The whole expression het eens zijn met corresponds to English agree with. Daarmee refers to with that; ermee refers to with it. Het remains a fixed part of the Dutch expression. Do not interpret the English word agree as a word-for-word translation of ben or eens alone.'}
})
fixes.update({
 'work-11':{'forms':'Deadline is a de-word: de deadline, een nieuwe deadline. Wanneer asks for a time or date; finite is comes before subject de deadline in this direct question.'},
 'work-12':{'forms':'Laten we introduces a suggestion shared by speaker and listener. Plannen remains an infinitive after laten we; een follow-up is its object. Compare present we plannen and simple past we planden.'},
 'work-13':{'forms':'Gewend zijn + te-infinitive describes an activity that is familiar: ik ben gewend lange uren te werken. Om is also possible: ik ben gewend om lange uren te werken. Lange has -e before plural uren; te werken remains an infinitive, not a second finite verb.','compare':'English be used to takes an -ing form here: working. Dutch uses a te-infinitive, optionally introduced by om. This is a current familiar activity, not English used to work meaning a former habit.'},
 'conversation-30':{'parts':[{'label':'subject','text':'We'},{'label':'finite verb (past auxiliary)','text':'hadden'},{'label':'adverb','text':'al'},{'label':'object','text':'een keuze'},{'label':'participle','text':'gemaakt'}]},
 'shopping-13':{'forms':'As a counting unit here, dozijn stays singular after twee. Het ei has irregular plural eieren. The noun after a unit need not always be plural: compare twee dozijn eieren with drie liter melk.','compare':'Both languages keep the counting unit singular here: English two dozen eggs, Dutch twee dozijn eieren. English dozens of eggs is a different construction.','practiceGuide':'The related bank practises short conversational expressions rather than only quantities. The measure examples use number + unit + item: twee kilo appels, drie liter melk. Appels is countable plural; melk is a mass noun. Thank-you examples practise a separate social formula, not a quantity rule.'},
 'administration-02':{'forms':'Laat is an imperative of laten: ask the listener to arrange the sending, possibly by a third person. Het is the item sent. Naar me gives its destination/recipient. Opsturen stays joined as an infinitive after laat; a direct command to send it yourself is Stuur het naar me op.','practiceGuide':'The related examples practise commands, including separable verbs and recipients. The parent is a causative command: Laat het naar me opsturen asks the listener to arrange for it to be sent. This differs from directly instructing the listener Stuur het me op. Both use an imperative, but the person carrying out the sending need not be the same.'},
 'transport-17':{'forms':'Kennen: u kent; ik ken; past kende/kenden; perfect heb/heeft gekend. Here kennen means being familiar with a neighbourhood. Weten typically concerns information, as in Weet u waar het station is? Kennen is not limited to people and places: ik ken dit gevoel means I know this feeling.'},
 'leisure-04':{'forms':'Uitkijken naar means look forward to: we kijken uit naar de vakantie. Kijken is finite, uit is its separable particle, and naar introduces what is anticipated. A full naar-phrase may follow uit, so uit need not be the last word. Perfect: we hebben naar de vakantie uitgekeken.','compare':'English look forward to and Dutch uitkijken naar are whole expressions with different particles/prepositions. The Dutch finite verb is kijken, followed here by uit and the full phrase naar de vakantie.'},
 'home-15':{'compare':'English can say turned off the lights or turned the lights off. Dutch keeps uit inside the participle uitgedaan after had; it does not separate gedaan uit.'},
 'conversation-34':{'forms':'Lijken has irregular past leek (singular) and leken (plural). Here it is a linking verb meaning seem. Blij describes hij and has no attributive -e; heel means very. Compare the noun phrase een blije man.','compare':'English He seemed very happy and Dutch Hij leek heel blij both describe an apparent state. Dutch uses past leek and predicate adjective blij; no extra was is needed.'},
 'food-10':{'forms':'Betalen uses hebben in the perfect: ik heb betaald. The unstressed prefix be- prevents an extra ge-: betaald, not gebetaald. Rekening is a de-word and names the bill here.','practiceGuide':'These examples practise hebben + participle and objects before the participle. Dutch betalen can take what is paid for directly: het eten betalen means pay for the food. In Ik heb de taxi betaald, the intended meaning is paying the taxi fare/driver, not buying a taxi. Auxiliary choice is learned with the verb; this verb uses hebben.'},
 'work-17':{'forms':'We takes plural zullen. Het is the unstressed object it and comes before dan in this model. Bespreken means discuss and takes a direct object without over. After zullen it remains an infinitive without te.'},
 'shopping-15':{'forms':'Bezig zijn + te-infinitive describes an activity in progress: hij is bezig de winkel te sluiten. The object de winkel comes before te sluiten. Compare bezig met het sluiten van de winkel, which names the activity as a noun-like phrase.','practiceGuide':'The shared examples compare being occupied with an activity and having finished one. Bezig zijn met/te describes work in progress; klaar zijn met describes completion. Hij is klaar met het lezen van het boek does not mean he is still reading. The parent uses bezig + object + te-infinitive rather than met + noun-like activity.'},
 'work-18':{'forms':'Denken over iets means consider something. In we denken erover om een winkel te openen, erover points ahead to the proposed activity. Om introduces that infinitive clause and te stands immediately before openen. This reports consideration, not a settled plan.','compare':'English thinking about opening uses an -ing form. Dutch uses erover plus an om ... te clause here. Denken aan can instead mean think of or remember; do not treat every combination of aan/over as the same expression.'},
 'conversation-35':{'compare':'Both languages start with a modal and subject. Dutch places the time dinsdag before final afspreken; English places on Tuesday after meet. Both dinsdag and op dinsdag can name the day.'},
 'health-03':{'forms':'For how you feel, use zich voelen: ik voelde me, zij voelde zich, wij voelden ons. Voelde is singular simple past; een beetje softens moe. Voelen is not always reflexive: ik voelde de stof means I felt the fabric.'},
 'conversation-38':{'forms':'Verzetten means reschedule in this appointment context, without specifying whether the new time is earlier or later. Uitstellen means postpone to a later time. Dit stands alone for the arrangement; it is not attached to an omitted noun whose article you must guess.','practiceGuide':'The bank practises modal questions with an infinitive. Related examples can change the situation: dit uitstellen and dit later doen explicitly move something later, while verzetten alone only changes the time. Keep that distinction when using a related example for a new situation.'}
})
fixes.update({
 'conversation-39':{'forms':'Verbergen: verbergt, verborg/verborgen, heeft verborgen. The unstressed prefix ver- does not add ge-. Voor ons in iets voor ons verbergen means from us, not for our benefit. Compare voor jou bewaren, where voor does name a beneficiary.'},
 'shopping-17':{'forms':'Dragen has irregular past droeg (singular), droegen (plural), and participle gedragen. Here it means wear clothing, so droeg can naturally be English was wearing. The same Dutch verb can mean carry in another context.'},
 'health-04':{'forms':'Gaan zitten means sit down or take a seat; plural ze takes gaan. The first ze is subject they. In tot de dokter ze roept, de dokter is the subject and the second ze is object them. Roept is singular because it agrees with de dokter, not with ze.','compare':'English until the doctor calls them puts calls before them. Dutch tot de dokter ze roept puts object ze before final roept. The sitting begins after gaan zitten; the English will sit conveys this next action.','practiceGuide':'These examples practise posture and movement into a posture. Gaan zitten and gaan staan mean sit down and stand up; zitten and staan alone describe the state. In the example Ze gaan staan tot de bus komt, they get up and remain standing until the bus comes. A tot-clause has its own final finite verb.'},
 'conversation-42':{'forms':'Werken has stem werk, so singular simple past is werk + te = werkte, not werken + te. De eerste keer means the first time. Niet negates working successfully in that instance.','compare':'English It did not work needs did plus bare work. Dutch puts the past directly in werkte and adds niet. Dutch needs no counterpart of did here.'},
 'transport-24':{'forms':'Iets nodig hebben means need something: ik heb een kaart nodig. Heb is a present finite verb, not a perfect auxiliary here. Kaart means a map in this navigation scenario; in another context it can mean a card or ticket.'},
 'health-05':{'forms':'Here was is present of wassen, not past of zijn: ik was mijn handen means I wash my hands. Compare jij/hij wast, wij wassen; past waste/wasten; perfect heb gewassen. Voor elke maaltijd means before every meal. Mijn is possessive my before plural handen.'},
 'transport-25':{'forms':'Klaar zijn om te + infinitive means be ready to act: ik ben klaar om te gaan. This describes readiness, not completed departure. Compare klaar met eten (finished eating) and klaar om te eten (ready to eat).'},
 'work-19':{'forms':'Te laat komen means arrive late. Te modifies laat (too/late), not a following infinitive. Soms means sometimes. Door het verkeer gives the cause, with het because verkeer is a het-word.'},
 'home-17':{'parts':[{'label':'subject','text':'Ze'},{'label':'finite verb (past modal)','text':'wilden'},{'label':'direction','text':'naar een groter huis'},{'label':'infinitive (inseparable verb)','text':'verhuizen'}],'forms':'Wilden is plural past of willen. Verhuizen is inseparable: ik verhuis, not ik huis ver. It stays an infinitive without te after wilden. Huis is a singular het-word, so use een groter huis; compare het grotere huis.','compare':'English wanted to move uses to. Dutch wilden takes the bare infinitive verhuizen, with naar een groter huis before it. This describes a wish, not proof that the move happened.'},
 'health-06':{'forms':'Wordt agrees with singular ze. Op een dag points to the future, so present wordt means will become here. The model uses the ordinary inflected adjective een geweldige dokter. Some adjectives before person or profession nouns can also be uninflected when describing that role; do not turn the model into a universal ban on such forms.','compare':'English uses will be for the future prediction. Dutch can use present wordt with future op een dag. Worden emphasises becoming a doctor, while zijn describes being one.'},
 'work-20':{'forms':'Ze means they here, so the past form is plural gebruikten, from stem gebruik + ten. Singular ze gebruikte would mean she used and is valid in a different situation. Voor de presentatie gives the purpose of using the room.'},
 'conversation-45':{'forms':'Wij takes plural zullen, and helpen remains an infinitive. Je is an object meaning you and comes before helpen in this model, not after it. This je is neither the subject nor possessive your.'},
 'home-18':{'forms':'Vies is a predicate adjective here and takes no agreement -e after is. Before an appropriate noun the spelling changes to vieze, with z: de vieze keuken. Viese is not the correct inflected spelling.'},
 'conversation-48':{'forms':'Geef is the ordinary imperative stem of geven. Its spelling changes from the infinitive: long ee is written in closed geef, and v becomes f. The irregular past is gaf/gaven and the participle is gegeven. Het is the thing and me the recipient in Geef het me.'},
 'weather-10':{'forms':'Kijken has irregular past keek/keken and participle gekeken. For looking at the sunset use kijken naar de zonsondergang. This is not a claim that every use of kijken requires naar: een film kijken is also possible.'},
 'administration-04':{'order':'This yes/no question starts with finite stuur, followed by subject je. Het is the thing sent and me the recipient. The separable particle op comes later; the finite verb is first here, not second.','forms':'Opsturen separates in this finite question: stuur je ... op. Compare statement je stuurt, where the added -t appears, with question stuur je. The present can make a request about the next action, naturally translated Will you send it to me?'},
 'work-22':{'forms':'Ontvangen has singular past ontving, plural ontvingen, and participle ontvangen. The unstressed prefix ont- prevents extra ge-. Ze is she here. Voor haar werk gives the reason for the award; haar means her before werk.'},
 'transport-27':{'forms':'Stond is singular past of staan; plural is stonden. Staan te wachten describes waiting while standing. The full location phrase bij de bushalte can follow te wachten, so the infinitive need not be the final word.'},
 'food-13':{'forms':'Drinken has irregular past dronk/dronken and participle gedronken. Ze is she here and takes heeft. Haar koffie is the object; niet before gedronken negates drinking that coffee in the intended situation.'}
})
# Full-record inspection, grammar positions 200–259. Historical examples remain intact.
fixes.update({
 'work-23':{'forms':'Praten over introduces the topic: ze praten over de details. Praten agrees with plural ze. The complete over-phrase can move with context; its final position here is not a universal rule.'},
 'conversation-53':{'meaning':'Asking the listener to give something back to the speaker and their group.','forms':'Teruggeven is separable: geef het ons terug. Het is the thing returned; ons means to us, including the speaker. Compare geef me mijn boek terug: a full noun object follows the short recipient pronoun.'},
 'conversation-54':{'forms':'Kunnen: ik kan. Het names the information and je names the listener receiving it. Nog niet means not yet; vertellen is an infinitive without te after kan. Ik kan het je vertellen means I can tell you; nog niet postpones that possibility.'},
 'conversation-55':{'forms':'Spreken has regular-looking present forms ik spreek, u spreekt and wij spreken, but irregular past sprak/spraken and participle gesproken. U retains spreekt in this polite question. Engels names the language without an article here.'},
 'leisure-12':{'forms':'Maken: maakte in the singular, maakten in the plural. Ze means they in this scenario and requires maakten. Ze maakte is valid for she made. Voor het weekend identifies the weekend being planned for.'},
 'leisure-13':{'forms':'Kijken has irregular past keek/keken and participle gekeken. Kijken naar is the model for watching this match. Kijken can also take a direct object in media contexts, as in een film kijken or voetbal kijken; naar is not compulsory in every use.'},
 'home-24':{'forms':'Schoon describes the condition of the thing, so it is a predicate adjective without agreement -e: het is schoon. Before a noun compare een schoon raam and het schone raam. The absence of -e is about this adjective function, not every word after zijn.'},
 'shopping-20':{'forms':'Dit is introduces an identification, even with a de-word: dit is mijn tas. It does not mean tas is a het-word. Before the noun itself use deze tas. Mijn means my before either a de-word or a het-word.'},
 'conversation-57':{'forms':'Vragen has past vroeg/vroegen and participle gevraagd. Ze means they here; ons is the group asked to come. Om vroeg te komen names their requested action. Om is optional in this complement: Ze vroegen ons vroeg te komen is also possible; te is retained.'},
 'transport-31':{'forms':'Passeren has regular past passeerde/passeerden and participle gepasseerd, with ge-. It does not have an unstressed prefix that blocks ge-. Wij takes plural passeerden. Here de bank is the bank passed on the route.'},
 'leisure-14':{'forms':'Verliezen: ik verlies; past verloor/verloren; perfect heb verloren. The model uses auxiliary hebt with subject je. Niet before verloren negates losing this match; other negation positions can change the contrast.'},
 'shopping-21':{'forms':'Betalen has past betaalde/betaalden and participle betaald without extra ge- because of unstressed be-. Ze means they here and takes betaalden; ze betaalde would mean she paid. Contant describes payment in cash. Meubels is plural in Dutch; English furniture is normally uncountable.'},
 'conversation-58':{'forms':'Vinden + object + adjective expresses an opinion: ik vind zijn auto leuk. Zijn is possessive his before auto, not the verb be. Leuk describes the object and stays uninflected. Compare the attributive adjective in zijn leuke auto.','practiceFocus':'Giving an opinion with vinden','practiceGuide':'Use a finite form of vinden, then the thing assessed and an adjective: Ik vind dit boek mooi. The adjective describes the object and normally has no agreement -e in this construction. Contrast een mooi boek and het mooie boek, where the adjective is attached to the noun.'},
 'conversation-60':{'forms':'Lang means tall for a person and long for a length. Here erg modifies lang (very tall). Lang is a predicate adjective without agreement -e; compare een lange man, where the adjective modifies a noun.'},
 'home-26':{'forms':'The present of wassen follows the ordinary pattern: ik was, jij/hij wast, wij wassen. The spelling removes one s in closed-syllable was; wast adds the ordinary -t. The past waste/wasten is regular, while the participle gewassen is irregular. Zijn means his before kleren.','compare':'English He washes his clothes at the laundrette uses present washes. Dutch uses present wast, with zijn kleren before the location in de wasserette.'},
 'conversation-61':{'meaning':'Saying that a man called the speaker this morning.','forms':'Bellen has regular past belde/belden and participle gebeld. Me (or stressed mij) is the object meaning me; hij is the subject. Vanmorgen means this morning and can refer to the earlier call.','compare':'English uses called; Dutch uses belde directly, without an auxiliary equivalent to did. The short object me comes before vanmorgen in this neutral model.'},
 'conversation-62':{'forms':'Zo means in a moment in ik ben zo terug; terug means back. This present-tense promise naturally corresponds to English I will be right back.'},
 'conversation-65':{'meaning':'Saying that a man gave the speaker good advice.','forms':'Geven has past gaf/gaven and participle gegeven. Me is the recipient and goed advies is the thing given. Advies is singular neuter and indefinite here, so use goed. Compare definite het goede advies and plural goede adviezen; a het-word does not forbid -e in every phrase.'},
 'work-24':{'forms':'Waar is the question word; werk is finite and subject je follows it. Omit the added second-person -t: je werkt becomes werk je. An embedded question has different order: Ik vraag waar je werkt.'},
 'conversation-66':{'forms':'Beter is the comparative of goed. The model uses an infinitive clause with om te helpen. Om can be omitted: Het is beter te helpen. Bare-infinitive evaluative expressions also exist, so learn this clause pattern without declaring every adjective plus infinitive invalid.'},
 'weather-12':{'compare':'English What is the weather like? and Dutch Wat voor weer is het? use different question phrases. Wat voor weer is one complete first constituent; finite is follows that whole phrase, not merely the first word.'},
 'school-18':{'meaning':'Saying that a woman explained something to the speaker.','forms':'This perfect uses hebben: zij heeft het mij uitgelegd. Uitleggen is separable: ze legt het uit; participle uit + ge + legd. Het is the thing explained and mij is the recipient. Compare unstressed me. Other perfects can use zijn, so hebben is not universal.'},
 'weather-13':{'forms':'Kijken has past keek/keken and participle gekeken. For looking at the sky, use kijken naar de lucht. Some media expressions instead allow a direct object, such as een film kijken; this does not license ze keek de lucht.'},
 'work-25':{'forms':'Oplossen splits in the main clause: we lossen problemen op. Zodra introduces the subordinate clause ze zich voordoen. Ze refers to the plural problems; zich is reflexive. Voordoen is a finite plural present here, not an infinitive despite the identical spelling. The separable verb stays joined at the end of this subordinate clause.'},
 'health-08':{'forms':'Volgen has present ik volg, hij volgt, wij volgen. In een gezond dieet, dieet is a singular het-word after indefinite een, so gezond has no -e. Compare het gezonde dieet.'},
 'conversation-69':{'forms':'Verliezen: ik verlies; past verloor/verloren; perfect heb verloren. Geduld is a het-word. Als introduces the situation triggering the reaction; plural mensen takes zijn at the end.'},
 'conversation-70':{'forms':'Bang zijn voor means be afraid of. Bang van also occurs and is particularly common in Belgium; do not reject it categorically. In the model voor de toekomst identifies what the speaker fears. Bang is a predicate adjective without agreement -e.'}
})
